	@Test
	void aControlFailureStillRestoresAllHarnessProperties() throws Exception {
		String nativeProperty = "rdf4j.lmdb.nativeQueryEngine.enabled";
		previous.put(nativeProperty, System.getProperty(nativeProperty));
		System.setProperty(nativeProperty, "TrUe");
		System.setProperty(PREFIX + "winnerControl", "true");
		System.setProperty(PREFIX + "protocol", "interleaved");
		System.setProperty(PREFIX + "queries", "distinctCities");
		System.setProperty(PREFIX + "output", dataDir.resolve("restoration.tsv").toString());
		Map<String, String> original = new LinkedHashMap<>();
		LmdbNativeGoldenDecisionsTest.STATIC_DECISION_PROPERTIES.keySet()
				.forEach(key -> original.put(key, System.getProperty(key)));
		try (MockedConstruction<SailRepository> repositories = mockConstruction(SailRepository.class,
				(repository, context) -> when(repository.getConnection())
						.thenReturn(mock(SailRepositoryConnection.class)));
				MockedConstruction<FoafCliqueDataGenerator> generators = mockConstruction(
						FoafCliqueDataGenerator.class);
				MockedStatic<AdjacencyEngagementTestAccess> adjacency = mockStatic(AdjacencyEngagementTestAccess.class);
				MockedStatic<LmdbNativeRegretHarness> harness = mockStatic(LmdbNativeRegretHarness.class,
						CALLS_REAL_METHODS)) {
			adjacency.when(() -> AdjacencyEngagementTestAccess.buildNow(any())).thenReturn(true);
			harness.when(() -> LmdbNativeRegretHarness.measureQueryInterleaved(any(), anyString(), anyString(),
					anyString(), anyString(), anyLong(), anyInt(), anyInt()))
					.thenReturn(List.of(timing("distinctCities")));
			harness.when(() -> LmdbNativeRegretHarness.measureWinnerControl(any(), anyString(), anyLong(), anyInt(),
					anyInt())).thenThrow(new QueryEvaluationException("synthetic control failure"));

			assertThatThrownBy(() -> new LmdbNativeStrategyRegretHarnessTest().measureEveryAdmittedStrategy())
					.isInstanceOf(QueryEvaluationException.class)
					.hasMessageContaining("synthetic control failure");
			original.forEach((key, value) -> assertThat(System.getProperty(key)).as(key).isEqualTo(value));
			assertThat(System.getProperty(PREFIX + "winnerControl")).isEqualTo("true");
		}
	}

