	private static Timing timing(String query) {
		return new Timing(query, "spoc,posc", "lmdbOnly", "row", "nestedLoop", true, true,
				100D, 90D, 1L, 100D, 100D, 100D, null, "successful=31; failed=0; notRun=0");
	}

	private static WinnerControl control() {
		Measurement measured = new Measurement(100D, 90D, 1L,
				"samplesNanos=[100]; successful=1; failed=0; notRun=0", null);
		return new WinnerControl("nestedLoop", null, measured, measured, true,
				"sampleOrder=AB/BA; fitEligible=false");
	}
